<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Change password · Sun Son Solar</title><link rel="stylesheet" href="<?= base_url('css/style.css') ?>"><link rel="stylesheet" href="<?= base_url('css/solar-app.css') ?>"><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet"></head><body class="passwordPage"><main class="passwordCard"><a class="appBrand" href="<?= site_url('/?view=storefront') ?>"><img src="<?= base_url('css/images/logo.png') ?>" alt=""><span>sun son<strong>solar</strong><small>SECURE ACCOUNT</small></span></a><span class="sectionKicker"><?= session()->get('must_change_password') ? 'FIRST SIGN-IN SECURITY' : 'ACCOUNT SECURITY' ?></span><h1><?= session()->get('must_change_password') ? 'Set your password.' : 'Change your password.' ?></h1><p><?= session()->get('must_change_password') ? 'Set a private password to finish signing in and open your workspace.' : 'Enter your current password, then choose a new password for your account.' ?></p><?php if ($errors = session()->getFlashdata('errors')): ?><div class="errorBox"><?php foreach ($errors as $error): ?><p><?= esc($error) ?></p><?php endforeach ?></div><?php endif ?><form method="post" action="<?= site_url('account/password') ?>"><?= csrf_field() ?><label>Current password<input class="formControl" type="password" name="current_password" autocomplete="current-password" required></label><label>New password<input class="formControl" type="password" name="new_password" autocomplete="new-password" minlength="12" required><small>Use at least 12 characters, including uppercase, lowercase, a number, and a symbol.</small></label><label>Confirm new password<input class="formControl" type="password" name="confirm_password" autocomplete="new-password" required></label><button class="primaryCta">Save new password <span>↗</span></button><?php if (!session()->get('must_change_password')): ?><a class="passwordCancel" href="<?= session()->get('role') === 'customer' ? site_url('customer') : site_url('admin') ?>">Return to dashboard</a><?php endif ?></form></main><script src="<?= base_url('js/tab-context.js') ?>" data-tab-context="<?= esc(session()->get('_active_tab_context')) ?>"></script></body></html>
